let questionPosition = 0;
const question = (prompt, options, correct, explanation) => {
  const answer = options[correct];
  const offset = questionPosition++ % options.length;
  const orderedOptions = [...options.slice(offset), ...options.slice(0, offset)];
  return {prompt, options: orderedOptions, answer, explanation};
};
